import{_ as a,o as t,c as s,a5 as p}from"./chunks/framework.CXroN2RO.js";const u=JSON.parse('{"title":"クラス名辞典","description":"","frontmatter":{"title":"クラス名辞典","study":{"source":"設計の手帖","kind":"用語","status":"既存原稿","summary":"設計の手帖に収録されている50の名前を、役割・例・注意点から引く辞典です。 分類: ドメイン 同一性を持ち、状態の変化を追う。 Entity と DB 行は常に同じ単位ではない。"}},"headers":[],"relativePath":"design/naming.md","filePath":"design/naming.md"}'),i={name:"design/naming.md"};function n(o,e,l,d,r,h){return t(),s("div",null,[...e[0]||(e[0]=[p('<h1 id="クラス名辞典" tabindex="-1">クラス名辞典 <a class="header-anchor" href="#クラス名辞典" aria-label="Permalink to &quot;クラス名辞典&quot;">​</a></h1><p>設計の手帖に収録されている50の名前を、役割・例・注意点から引く辞典です。</p><h2 id="0" tabindex="-1">Entity <a class="header-anchor" href="#0" aria-label="Permalink to &quot;Entity {#0}&quot;">​</a></h2><p>分類: ドメイン</p><p>同一性を持ち、状態の変化を追う。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Order / Customer</span></span></code></pre></div><p>Entity と DB 行は常に同じ単位ではない。</p><p><a href="/study/design/notebook/domain.html">DDD・Entity・Repository</a></p><h2 id="1" tabindex="-1">Value Object <a class="header-anchor" href="#1" aria-label="Permalink to &quot;Value Object {#1}&quot;">​</a></h2><p>分類: ドメイン</p><p>値で等しさを判断し、ルールをまとめる。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Money / DateRange / Quantity</span></span></code></pre></div><p>struct や record にするだけでは不変条件は保証されない。</p><p><a href="/study/design/notebook/objects.html">カプセル化と値オブジェクト</a></p><h2 id="2" tabindex="-1">Aggregate Root <a class="header-anchor" href="#2" aria-label="Permalink to &quot;Aggregate Root {#2}&quot;">​</a></h2><p>分類: ドメイン</p><p>整合性を守る集約の操作窓口。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Order / ShoppingCart</span></span></code></pre></div><p>関連データをすべて詰め込まない。</p><p><a href="/study/design/notebook/domain.html">DDD・Entity・Repository</a></p><h2 id="3" tabindex="-1">Domain Service <a class="header-anchor" href="#3" aria-label="Permalink to &quot;Domain Service {#3}&quot;">​</a></h2><p>分類: ドメイン</p><p>一つの Entity へ自然に属さない業務判断。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PricingService / TransferService</span></span></code></pre></div><p>取得と保存の調整をする Application Service と区別。</p><p><a href="/study/design/notebook/domain.html">DDD・Entity・Repository</a></p><h2 id="4" tabindex="-1">Specification <a class="header-anchor" href="#4" aria-label="Permalink to &quot;Specification {#4}&quot;">​</a></h2><p>分類: ドメイン</p><p>適合条件を名前のあるルールにする。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>EligibleCustomerSpecification</span></span></code></pre></div><p>単純な条件式まで型に分ける必要はない。</p><p><a href="/study/design/notebook/domain.html">DDD・Entity・Repository</a></p><h2 id="5" tabindex="-1">Policy <a class="header-anchor" href="#5" aria-label="Permalink to &quot;Policy {#5}&quot;">​</a></h2><p>分類: ドメイン</p><p>判断や制約を表す差し替え可能な方針。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ShippingPolicy / RetryPolicy</span></span></code></pre></div><p>技術的な再試行と業務の価格規則は別の責務。</p><p><a href="/study/design/notebook/behavior.html">Strategy・State・Command</a></p><h2 id="6" tabindex="-1">Repository <a class="header-anchor" href="#6" aria-label="Permalink to &quot;Repository {#6}&quot;">​</a></h2><p>分類: データ・境界</p><p>ドメインの集合として取得・保存を提供。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OrderRepository / IOrderRepository</span></span></code></pre></div><p>全テーブルに機械的に作るものではない。</p><p><a href="/study/design/notebook/domain.html">DDD・Entity・Repository</a></p><h2 id="7" tabindex="-1">DAO <a class="header-anchor" href="#7" aria-label="Permalink to &quot;DAO {#7}&quot;">​</a></h2><p>分類: データ・境界</p><p>データストアの操作をまとめる。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CustomerDao / UserDao</span></span></code></pre></div><p>Repository と役割が重なる運用もある。契約を見る。</p><p><a href="/study/design/notebook/domain.html">DDD・Entity・Repository</a></p><h2 id="8" tabindex="-1">DTO <a class="header-anchor" href="#8" aria-label="Permalink to &quot;DTO {#8}&quot;">​</a></h2><p>分類: データ・境界</p><p>境界を越えてデータを運ぶ形。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OrderSummaryDto / CustomerDto</span></span></code></pre></div><p>業務モデルや画面状態との共用は変更理由を確認。</p><p><a href="/study/design/notebook/domain.html">DDD・Entity・Repository</a></p><h2 id="9" tabindex="-1">Request / Response <a class="header-anchor" href="#9" aria-label="Permalink to &quot;Request / Response {#9}&quot;">​</a></h2><p>分類: データ・境界</p><p>入口の入力と、出口の応答を表す。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CreateOrderRequest / OrderResponse</span></span></code></pre></div><p>内部モデルの全項目をそのまま公開しない。</p><p><a href="/study/design/notebook/architecture.html">レイヤーとアーキテクチャ</a></p><h2 id="10" tabindex="-1">Mapper / Converter <a class="header-anchor" href="#10" aria-label="Permalink to &quot;Mapper / Converter {#10}&quot;">​</a></h2><p>分類: データ・境界</p><p>データ表現や型を変換する。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OrderMapper / CurrencyConverter</span></span></code></pre></div><p>通貨換算など業務判断を含むなら責務を明確に。</p><p><a href="/study/design/notebook/structure.html">Adapter・Decorator・Facade</a></p><h2 id="11" tabindex="-1">Serializer / Deserializer <a class="header-anchor" href="#11" aria-label="Permalink to &quot;Serializer / Deserializer {#11}&quot;">​</a></h2><p>分類: データ・境界</p><p>型と、保存・通信する形式を相互変換。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>JsonOrderSerializer</span></span></code></pre></div><p>形式変更と業務判断を混ぜない。</p><p><a href="/study/design/notebook/structure.html">Adapter・Decorator・Facade</a></p><h2 id="12" tabindex="-1">Gateway / Client <a class="header-anchor" href="#12" aria-label="Permalink to &quot;Gateway / Client {#12}&quot;">​</a></h2><p>分類: データ・境界</p><p>外部サービスとの通信の窓口。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PaymentGateway / WeatherApiClient</span></span></code></pre></div><p>タイムアウト、エラー変換、所有する接続を決める。</p><p><a href="/study/design/notebook/architecture.html">レイヤーとアーキテクチャ</a></p><h2 id="13" tabindex="-1">UnitOfWork <a class="header-anchor" href="#13" aria-label="Permalink to &quot;UnitOfWork {#13}&quot;">​</a></h2><p>分類: データ・境界</p><p>変更の追跡やトランザクションを調整。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OrderUnitOfWork / DbContext</span></span></code></pre></div><p>既存 ORM の機能と重ねる前に必要性を確認。</p><p><a href="/study/design/notebook/domain.html">DDD・Entity・Repository</a></p><h2 id="14" tabindex="-1">QueryService / Reader <a class="header-anchor" href="#14" aria-label="Permalink to &quot;QueryService / Reader {#14}&quot;">​</a></h2><p>分類: データ・境界</p><p>参照専用の取得や投影を担う。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OrderQueryService / ReportReader</span></span></code></pre></div><p>更新側の不変条件を迂回する書き込みを混ぜない。</p><p><a href="/study/design/notebook/paradigms.html">関数型・データ指向・CQRS</a></p><h2 id="15" tabindex="-1">Adapter <a class="header-anchor" href="#15" aria-label="Permalink to &quot;Adapter {#15}&quot;">​</a></h2><p>分類: 構造・生成</p><p>外側の契約を利用側の契約へ適合。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LegacyPaymentAdapter</span></span></code></pre></div><p>API と単位、例外の意味も翻訳する。</p><p><a href="/study/design/notebook/structure.html">Adapter・Decorator・Facade</a></p><h2 id="16" tabindex="-1">Decorator <a class="header-anchor" href="#16" aria-label="Permalink to &quot;Decorator {#16}&quot;">​</a></h2><p>分類: 構造・生成</p><p>同じ契約を包んで機能を追加。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LoggingRepository / CompressingStream</span></span></code></pre></div><p>包む順序による振る舞いの変化に注意。</p><p><a href="/study/design/notebook/structure.html">Adapter・Decorator・Facade</a></p><h2 id="17" tabindex="-1">Facade <a class="header-anchor" href="#17" aria-label="Permalink to &quot;Facade {#17}&quot;">​</a></h2><p>分類: 構造・生成</p><p>複数の処理へ簡潔な入口を提供。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CheckoutFacade / MediaFacade</span></span></code></pre></div><p>すべての業務を抱える巨大な入口にしない。</p><p><a href="/study/design/notebook/structure.html">Adapter・Decorator・Facade</a></p><h2 id="18" tabindex="-1">Proxy <a class="header-anchor" href="#18" aria-label="Permalink to &quot;Proxy {#18}&quot;">​</a></h2><p>分類: 構造・生成</p><p>対象へのアクセスを代理・制御。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LazyImageProxy / RemoteServiceProxy</span></span></code></pre></div><p>ローカル呼び出しと通信の失敗の違いを隠しすぎない。</p><p><a href="/study/design/notebook/structure.html">Adapter・Decorator・Facade</a></p><h2 id="19" tabindex="-1">Factory <a class="header-anchor" href="#19" aria-label="Permalink to &quot;Factory {#19}&quot;">​</a></h2><p>分類: 構造・生成</p><p>生成手順や実装の選択をまとめる。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ParserFactory / ConnectionFactory</span></span></code></pre></div><p>GoF Factory Method と単純な factory 関数を区別。</p><p><a href="/study/design/notebook/creation.html">Factory・Builder・Singleton</a></p><h2 id="20" tabindex="-1">Builder <a class="header-anchor" href="#20" aria-label="Permalink to &quot;Builder {#20}&quot;">​</a></h2><p>分類: 構造・生成</p><p>段階的に組み立てて完成品を作る。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ReportBuilder / QueryBuilder</span></span></code></pre></div><p>完成時に必要条件を検証する。</p><p><a href="/study/design/notebook/creation.html">Factory・Builder・Singleton</a></p><h2 id="21" tabindex="-1">Composite <a class="header-anchor" href="#21" aria-label="Permalink to &quot;Composite {#21}&quot;">​</a></h2><p>分類: 構造・生成</p><p>単体と集合を同じ操作で扱う。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ShapeGroup / CompositeRule</span></span></code></pre></div><p>すべての操作が単体・集合の両方に自然か確認。</p><p><a href="/study/design/notebook/structure.html">Adapter・Decorator・Facade</a></p><h2 id="22" tabindex="-1">Bridge <a class="header-anchor" href="#22" aria-label="Permalink to &quot;Bridge {#22}&quot;">​</a></h2><p>分類: 構造・生成</p><p>抽象と実装の二つの変動軸を分離。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Shape + Renderer</span></span></code></pre></div><p>変動軸が一つだけなら過剰な可能性がある。</p><p><a href="/study/design/notebook/structure.html">Adapter・Decorator・Facade</a></p><h2 id="23" tabindex="-1">Strategy <a class="header-anchor" href="#23" aria-label="Permalink to &quot;Strategy {#23}&quot;">​</a></h2><p>分類: 振る舞い</p><p>同じ目的のアルゴリズムを差し替える。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DiscountStrategy / SortStrategy</span></span></code></pre></div><p>一操作なら関数やデリゲートでも表せる。</p><p><a href="/study/design/notebook/behavior.html">Strategy・State・Command</a></p><h2 id="24" tabindex="-1">State <a class="header-anchor" href="#24" aria-label="Permalink to &quot;State {#24}&quot;">​</a></h2><p>分類: 振る舞い</p><p>状態ごとの振る舞いと遷移をまとめる。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DraftState / ApprovedState</span></span></code></pre></div><p>少数の状態なら enum と遷移表で足りることも。</p><p><a href="/study/design/notebook/behavior.html">Strategy・State・Command</a></p><h2 id="25" tabindex="-1">Command <a class="header-anchor" href="#25" aria-label="Permalink to &quot;Command {#25}&quot;">​</a></h2><p>分類: 振る舞い</p><p>実行する操作と引数をひとまとめにする。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RenameFileCommand / PlaceOrderCommand</span></span></code></pre></div><p>自動で Undo や冪等性が得られるわけではない。</p><p><a href="/study/design/notebook/behavior.html">Strategy・State・Command</a></p><h2 id="26" tabindex="-1">Handler <a class="header-anchor" href="#26" aria-label="Permalink to &quot;Handler {#26}&quot;">​</a></h2><p>分類: 振る舞い</p><p>特定の要求・通知を受けて処理する。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PlaceOrderHandler / OrderPlacedHandler</span></span></code></pre></div><p>何を扱うかを名前に含める。</p><p><a href="/study/design/notebook/events.html">Observer とイベント設計</a></p><h2 id="27" tabindex="-1">Observer / Subscriber <a class="header-anchor" href="#27" aria-label="Permalink to &quot;Observer / Subscriber {#27}&quot;">​</a></h2><p>分類: 振る舞い</p><p>対象の変化や通知を購読する。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>InventoryObserver / OrderSubscriber</span></span></code></pre></div><p>購読解除と発行元との寿命関係に注意。</p><p><a href="/study/design/notebook/events.html">Observer とイベント設計</a></p><h2 id="28" tabindex="-1">Publisher / EventBus <a class="header-anchor" href="#28" aria-label="Permalink to &quot;Publisher / EventBus {#28}&quot;">​</a></h2><p>分類: 振る舞い</p><p>通知を発行・配信する窓口。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DomainEventPublisher / EventBus</span></span></code></pre></div><p>配信順序、同期性、失敗時の扱いを明示。</p><p><a href="/study/design/notebook/events.html">Observer とイベント設計</a></p><h2 id="29" tabindex="-1">Mediator <a class="header-anchor" href="#29" aria-label="Permalink to &quot;Mediator {#29}&quot;">​</a></h2><p>分類: 振る舞い</p><p>複数の部品や要求の調整を仲介。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DialogMediator / RequestMediator</span></span></code></pre></div><p>全業務を抱える司令塔にしない。</p><p><a href="/study/design/notebook/events.html">Observer とイベント設計</a></p><h2 id="30" tabindex="-1">Validator <a class="header-anchor" href="#30" aria-label="Permalink to &quot;Validator {#30}&quot;">​</a></h2><p>分類: 振る舞い</p><p>入力や候補が条件を満たすか検査。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CreateOrderValidator</span></span></code></pre></div><p>境界の検証とモデルの不変条件を区別。</p><p><a href="/study/design/notebook/objects.html">カプセル化と値オブジェクト</a></p><h2 id="31" tabindex="-1">Parser <a class="header-anchor" href="#31" aria-label="Permalink to &quot;Parser {#31}&quot;">​</a></h2><p>分類: 振る舞い</p><p>入力を文法に従って構造へ変換。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CsvParser / ExpressionParser</span></span></code></pre></div><p>文字列分割とエラー位置の契約を明確に。</p><p><a href="/study/design/notebook/creation.html">Factory・Builder・Singleton</a></p><h2 id="32" tabindex="-1">Processor / Pipeline <a class="header-anchor" href="#32" aria-label="Permalink to &quot;Processor / Pipeline {#32}&quot;">​</a></h2><p>分類: 振る舞い</p><p>一連の処理や複数ステップを実行。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ImageProcessor / ImportPipeline</span></span></code></pre></div><p>何でも受ける汎用型へ広げすぎない。</p><p><a href="/study/design/notebook/behavior.html">Strategy・State・Command</a></p><h2 id="33" tabindex="-1">UseCase / ApplicationService <a class="header-anchor" href="#33" aria-label="Permalink to &quot;UseCase / ApplicationService {#33}&quot;">​</a></h2><p>分類: アプリ・UI</p><p>ユースケースの取得・操作・保存を調整。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PlaceOrderUseCase / OrderAppService</span></span></code></pre></div><p>業務判断を全部ここへ詰め込まない。</p><p><a href="/study/design/notebook/architecture.html">レイヤーとアーキテクチャ</a></p><h2 id="34" tabindex="-1">Controller <a class="header-anchor" href="#34" aria-label="Permalink to &quot;Controller {#34}&quot;">​</a></h2><p>分類: アプリ・UI</p><p>入力を受け、処理を呼び、結果を応答へ。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OrderController / InputController</span></span></code></pre></div><p>HTTP や UI の詳細をドメインへ渡さない。</p><p><a href="/study/design/notebook/presentation.html">MVC・MVP・MVVM</a></p><h2 id="35" tabindex="-1">Presenter <a class="header-anchor" href="#35" aria-label="Permalink to &quot;Presenter {#35}&quot;">​</a></h2><p>分類: アプリ・UI</p><p>View の契約を通じて表示を調整。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OrderPresenter / LoginPresenter</span></span></code></pre></div><p>View と業務モデルの橋渡しへ責務を絞る。</p><p><a href="/study/design/notebook/presentation.html">MVC・MVP・MVVM</a></p><h2 id="36" tabindex="-1">ViewModel <a class="header-anchor" href="#36" aria-label="Permalink to &quot;ViewModel {#36}&quot;">​</a></h2><p>分類: アプリ・UI</p><p>表示状態と操作を View へ公開。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OrderViewModel / SearchViewModel</span></span></code></pre></div><p>Model・DTO と同じものではない。</p><p><a href="/study/design/notebook/presentation.html">MVC・MVP・MVVM</a></p><h2 id="37" tabindex="-1">View <a class="header-anchor" href="#37" aria-label="Permalink to &quot;View {#37}&quot;">​</a></h2><p>分類: アプリ・UI</p><p>画面や表示を担当。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OrderView / MainWindow</span></span></code></pre></div><p>業務判断をイベントハンドラーへ集中させない。</p><p><a href="/study/design/notebook/presentation.html">MVC・MVP・MVVM</a></p><h2 id="38" tabindex="-1">Model <a class="header-anchor" href="#38" aria-label="Permalink to &quot;Model {#38}&quot;">​</a></h2><p>分類: アプリ・UI</p><p>対象を表すモデル。意味は文脈依存。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OrderModel / DocumentModel</span></span></code></pre></div><p>DB 行、業務型、UI 用モデルのどれか確認。</p><p><a href="/study/design/notebook/presentation.html">MVC・MVP・MVVM</a></p><h2 id="39" tabindex="-1">Coordinator <a class="header-anchor" href="#39" aria-label="Permalink to &quot;Coordinator {#39}&quot;">​</a></h2><p>分類: アプリ・UI</p><p>画面遷移や複数処理の進行を調整。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NavigationCoordinator</span></span></code></pre></div><p>アプリ全体の万能 Manager にしない。</p><p><a href="/study/design/notebook/presentation.html">MVC・MVP・MVVM</a></p><h2 id="40" tabindex="-1">Service <a class="header-anchor" href="#40" aria-label="Permalink to &quot;Service {#40}&quot;">​</a></h2><p>分類: アプリ・UI</p><p>特定の機能・操作を提供。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>EmailService / PricingService</span></span></code></pre></div><p>技術処理か業務判断か、名前と配置で伝える。</p><p><a href="/study/design/notebook/naming.html">クラス名の読み方・付け方</a></p><h2 id="41" tabindex="-1">Manager / Helper / Utils <a class="header-anchor" href="#41" aria-label="Permalink to &quot;Manager / Helper / Utils {#41}&quot;">​</a></h2><p>分類: アプリ・UI</p><p>管理や補助。意味が広いので要注意。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SessionManager / PathHelper</span></span></code></pre></div><p>曖昧なら対象と具体的な動詞・役割へ絞る。</p><p><a href="/study/design/notebook/naming.html">クラス名の読み方・付け方</a></p><h2 id="42" tabindex="-1">ScopeGuard / Handle <a class="header-anchor" href="#42" aria-label="Permalink to &quot;ScopeGuard / Handle {#42}&quot;">​</a></h2><p>分類: 言語・基盤</p><p>スコープ終了時の処理やリソースを管理。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FileHandle / ScopeGuard</span></span></code></pre></div><p>C++ なら例外、ムーブ、所有権の契約も考える。</p><p><a href="/study/design/notebook/cpp.html">C++ の所有権と型設計</a></p><h2 id="43" tabindex="-1">Impl / Pimpl <a class="header-anchor" href="#43" aria-label="Permalink to &quot;Impl / Pimpl {#43}&quot;">​</a></h2><p>分類: 言語・基盤</p><p>公開型から実装詳細を隠す。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Document::Impl</span></span></code></pre></div><p>不完全型と特殊メンバー関数の定義場所に注意。</p><p><a href="/study/design/notebook/cpp.html">C++ の所有権と型設計</a></p><h2 id="44" tabindex="-1">Provider <a class="header-anchor" href="#44" aria-label="Permalink to &quot;Provider {#44}&quot;">​</a></h2><p>分類: 言語・基盤</p><p>必要な値や機能の供給元。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TimeProvider / TokenProvider</span></span></code></pre></div><p>Service Locator 的に何でも取得させない。</p><p><a href="/study/design/notebook/composition.html">合成・インターフェース・DI</a></p><h2 id="45" tabindex="-1">Exception / Error <a class="header-anchor" href="#45" aria-label="Permalink to &quot;Exception / Error {#45}&quot;">​</a></h2><p>分類: 言語・基盤</p><p>失敗の種類や情報を表す。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OrderNotFoundException / ParseError</span></span></code></pre></div><p>C# の Exception 語尾と、C++ の失敗表現は区別。</p><p><a href="/study/design/notebook/csharp.html">C# の寿命と非同期設計</a></p><h2 id="46" tabindex="-1">EventArgs / EventHandler <a class="header-anchor" href="#46" aria-label="Permalink to &quot;EventArgs / EventHandler {#46}&quot;">​</a></h2><p>分類: 言語・基盤</p><p>C# のイベント情報 / 通知を扱う型名。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OrderChangedEventArgs / EventHandler&lt;T&gt;</span></span></code></pre></div><p>EventHandler は標準型、独自の語尾は慣例。</p><p><a href="/study/design/notebook/events.html">Observer とイベント設計</a></p><h2 id="47" tabindex="-1">Options / Settings / Config <a class="header-anchor" href="#47" aria-label="Permalink to &quot;Options / Settings / Config {#47}&quot;">​</a></h2><p>分類: 言語・基盤</p><p>構成や選択可能な設定をまとめる。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ImportOptions / SmtpSettings</span></span></code></pre></div><p>秘密情報をログへ出さず、設定値も検証する。</p><p><a href="/study/design/notebook/creation.html">Factory・Builder・Singleton</a></p><h2 id="48" tabindex="-1">Cache / Pool <a class="header-anchor" href="#48" aria-label="Permalink to &quot;Cache / Pool {#48}&quot;">​</a></h2><p>分類: 言語・基盤</p><p>結果の再利用 / 資源の貸出と返却。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ProductCache / ConnectionPool</span></span></code></pre></div><p>無効化、容量、同時利用、返却時の状態を設計。</p><p><a href="/study/design/notebook/cpp.html">C++ の所有権と型設計</a></p><h2 id="49" tabindex="-1">Fake / Stub / Mock / Spy <a class="header-anchor" href="#49" aria-label="Permalink to &quot;Fake / Stub / Mock / Spy {#49}&quot;">​</a></h2><p>分類: テスト</p><p>本物の代わりに応答・記録・検証する。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FakeRepository / RecordingNotifier</span></span></code></pre></div><p>何を検証する代役かを先に決める。</p><p><a href="/study/design/notebook/practice.html">実践課題とレビューの視点</a></p>',302)])])}const b=a(i,[["render",n]]);export{u as __pageData,b as default};
